import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Find the k-th largest element in an unsorted list using the Quickselect algorithm.
    The average time complexity is O(n), and the worst-case is O(n^2), which occurs 
    in cases of poor pivot selection.
    """

    if k < 1 or k > len(nums):
        return None

    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # for k-th largest we want greater than
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left, right, k_smallest):
        if left == right:
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return quickselect(left, pivot_index - 1, k_smallest)
        else:
            return quickselect(pivot_index + 1, right, k_smallest)

    return quickselect(0, len(nums) - 1, k - 1)

import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Find the k-th largest element in an unsorted list using the Median of Medians algorithm.
    The average and worst-case time complexity is O(n).
    """

    if k < 1 or k > len(nums):
        return None

    def median_of_medians(left, right):
        if right - left < 5:
            return sorted(nums[left:right + 1])[(right - left) // 2]

        medians = []
        for i in range(left, right + 1, 5):
            sub_right = min(i + 4, right)
            medians.append(sorted(nums[i:sub_right + 1])[(sub_right - i) // 2])
        return median_of_medians(left=0, right=len(medians) - 1)

    def partition(left, right, pivot):
        pivot_value = nums[pivot]
        nums[pivot], nums[right] = nums[right], nums[pivot]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    left, right = 0, len(nums) - 1
    while True:
        pivot_index = nums.index(median_of_medians(left, right))
        pivot_index = partition(left, right, pivot_index)

        if pivot_index == k - 1:
            return nums[pivot_index]
        elif pivot_index < k - 1:
            left = pivot_index + 1
        else:
            right = pivot_index - 1

def kth_largest(nums: list[int], k: int) -> int:
    """
    Find the k-th largest element in an unsorted list using the binary search method 
    on the range of possible values. The average time complexity is O(n log(m - n)),
    where m is the range of values in nums.
    """

    if k < 1 or k > len(nums):
        return None

    def count_less_equal(mid):
        count = 0
        for num in nums:
            if num <= mid:
                count += 1
        return count

    left, right = min(nums), max(nums)

    while left < right:
        mid = (left + right) // 2
        if count_less_equal(mid) < len(nums) - k + 1:
            left = mid + 1
        else:
            right = mid

    return left
